// ==== 17-auth.js ====
// ---------- Accounts (Supabase Auth) ----------
// Shared across every page that includes this script (index.html, account.html). Handles
// sign up / log in / log out and keeps the header's auth chip in sync. Other scripts (like
// 14-buy-sell-redirect.js and account.html's own page script) listen for the 'cw:auth' event on
// `document` rather than reaching into this module directly, so load order doesn't matter:
//   document.addEventListener('cw:auth', (e) => { const user = e.detail.user; ... });
// `window.cwAuth.getUser()` is also available for a one-off synchronous-ish read (returns
// whatever the last known session was; null until the initial session check resolves).

(function () {
    let supabaseClient = null;
    let currentUser = null;
    let configured = false;
    let resolved = false; // true once the initial getSession() check has completed at least once
    const changeListeners = [];

    if (typeof CW_CONFIG !== 'undefined' && CW_CONFIG.supabaseUrl && CW_CONFIG.supabaseAnonKey && typeof supabase !== 'undefined') {
        try {
            supabaseClient = supabase.createClient(CW_CONFIG.supabaseUrl, CW_CONFIG.supabaseAnonKey);
            configured = true;
        } catch (err) {
            console.error('[CryptoBolt] Failed to initialize Supabase client:', err.message);
        }
    } else {
        console.info('[CryptoBolt] Supabase not configured — accounts are disabled until supabaseUrl/supabaseAnonKey are set in js/00-config.js.');
    }

    function broadcastAuth() {
        resolved = true;
        document.dispatchEvent(new CustomEvent('cw:auth', { detail: { user: currentUser, configured } }));
        changeListeners.forEach(cb => cb(currentUser, configured));
    }

    window.cwAuth = {
        getUser: () => currentUser,
        isConfigured: () => configured,
        getClient: () => supabaseClient,
        // Registers a callback for auth state changes. If the initial session check has already
        // resolved by the time this is called (a real possibility — supabase-js can resolve
        // getSession() from a cached local session before the next <script> tag even runs), the
        // callback fires immediately with the current state instead of only on the NEXT change.
        // This is the safe way for another page script to learn the current user; listening for
        // the 'cw:auth' document event alone can race and miss the first broadcast.
        onChange: (callback) => {
            changeListeners.push(callback);
            if (resolved) callback(currentUser, configured);
        },
    };

    // ---------- Header chip (present on any page that includes this markup) ----------
    const openBtn = document.getElementById('auth-open-btn');
    const userChip = document.getElementById('auth-user-chip');
    const userEmailEl = document.getElementById('auth-user-email');
    const signOutBtn = document.getElementById('auth-signout-btn');

    function renderHeader() {
        if (!openBtn || !userChip) return;
        if (currentUser) {
            openBtn.classList.add('hidden');
            userChip.classList.remove('hidden');
            userChip.classList.add('flex');
            if (userEmailEl) userEmailEl.title = currentUser.email || '';
        } else {
            openBtn.classList.remove('hidden');
            userChip.classList.add('hidden');
            userChip.classList.remove('flex');
        }
    }

    if (signOutBtn) {
        signOutBtn.addEventListener('click', async () => {
            if (!supabaseClient) return;
            await supabaseClient.auth.signOut();
        });
    }

    // ---------- Auth modal (sign up / log in / forgot password) ----------
    const modal = document.getElementById('auth-modal');
    if (modal) {
        const tabSignIn = document.getElementById('auth-tab-signin');
        const tabSignUp = document.getElementById('auth-tab-signup');
        const usernameWrap = document.getElementById('auth-username-wrap');
        const usernameInput = document.getElementById('auth-username-input');
        const emailInput = document.getElementById('auth-email-input');
        const passwordInput = document.getElementById('auth-password-input');
        const submitBtn = document.getElementById('auth-submit-btn');
        const errorEl = document.getElementById('auth-error');
        const infoEl = document.getElementById('auth-info');
        const forgotLink = document.getElementById('auth-forgot-link');
        const configWarning = document.getElementById('auth-config-warning');
        const USERNAME_RE = /^[A-Za-z0-9_]{3,20}$/;
        let mode = 'signin'; // 'signin' | 'signup'
        let previousFocus = null;
        const modalCard = modal.querySelector('[role="dialog"]');

        function setMode(next) {
            mode = next;
            tabSignIn.classList.toggle('auth-tab-active', mode === 'signin');
            tabSignUp.classList.toggle('auth-tab-active', mode === 'signup');
            usernameWrap?.classList.toggle('hidden', mode !== 'signup');
            submitBtn.innerText = mode === 'signin' ? 'Sign In' : 'Create Account';
            forgotLink.classList.toggle('hidden', mode !== 'signin');
            errorEl.classList.add('hidden');
            infoEl.classList.add('hidden');
        }
        tabSignIn?.addEventListener('click', () => setMode('signin'));
        tabSignUp?.addEventListener('click', () => setMode('signup'));

        function openModal() {
            previousFocus = document.activeElement;
            if (!configured) {
                configWarning?.classList.remove('hidden');
            } else {
                configWarning?.classList.add('hidden');
            }
            errorEl.classList.add('hidden');
            infoEl.classList.add('hidden');
            emailInput.value = '';
            passwordInput.value = '';
            if (usernameInput) usernameInput.value = '';
            modal.classList.add('cw-visible');
            setMode('signin');
            emailInput?.focus();
        }
        function closeModal() {
            modal.classList.remove('cw-visible');
            previousFocus?.focus?.();
        }

        openBtn?.addEventListener('click', openModal);
        document.getElementById('auth-modal-close')?.addEventListener('click', closeModal);
        modal.addEventListener('click', (e) => { if (e.target === modal) closeModal(); });
        document.addEventListener('keydown', (e) => {
            if (!modal.classList.contains('cw-visible')) return;
            if (e.key === 'Escape') { closeModal(); return; }
            if (e.key !== 'Tab' || !modalCard) return;
            const focusable = [...modalCard.querySelectorAll('button:not([disabled]), input, a[href]')];
            if (!focusable.length) return;
            const first = focusable[0];
            const last = focusable[focusable.length - 1];
            if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
            else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
        });

        function showError(msg) { errorEl.innerText = msg; errorEl.classList.remove('hidden'); infoEl.classList.add('hidden'); }
        function showInfo(msg) { infoEl.innerText = msg; infoEl.classList.remove('hidden'); errorEl.classList.add('hidden'); }

        submitBtn?.addEventListener('click', async () => {
            if (!supabaseClient) { showError('Accounts are not set up yet on this deployment.'); return; }
            const email = emailInput.value.trim();
            const password = passwordInput.value;
            const username = usernameInput ? usernameInput.value.trim() : '';
            if (!email || !/^\S+@\S+\.\S+$/.test(email)) { showError('Enter a valid email address.'); return; }
            if (!password || password.length < 6) { showError('Password must be at least 6 characters.'); return; }
            if (mode === 'signup' && !USERNAME_RE.test(username)) {
                showError('Username must be 3-20 characters — letters, numbers, and underscores only.');
                return;
            }

            submitBtn.disabled = true;
            const originalLabel = submitBtn.innerText;
            submitBtn.innerText = 'Please wait…';
            try {
                if (mode === 'signup') {
                    // The username is handed to Postgres via raw_user_meta_data — a
                    // database trigger (handle_new_user(), see supabase/schema.sql) copies
                    // it into the public "profiles" table the instant the account row is
                    // created, so it works identically for this form and for "Continue with
                    // Google" (which never touches this code path but still gets a
                    // fallback username from that same trigger).
                    // ref: this signup's referral code, if the visitor arrived via a friend's
                    // ?ref= link (js/24-referrals.js stashes it in localStorage on arrival).
                    // handle_new_user() in supabase/schema.sql records the referral from it.
                    const ref = window.cwReferral ? window.cwReferral.getStoredRefCode() : '';
                    const signUpData = ref ? { username, ref } : { username };
                    const { data, error } = await supabaseClient.auth.signUp({ email, password, options: { data: signUpData } });
                    if (error) {
                        // Some Supabase configs throw this outright for a duplicate email.
                        if (/already registered|already exists|user already/i.test(error.message || '')) {
                            setMode('signin');
                            emailInput.value = email;
                            passwordInput.value = '';
                            showError('An account with this email already exists — sign in instead, or use "Forgot password?" below.');
                            passwordInput.focus();
                            return;
                        }
                        throw error;
                    }
                    // With email confirmations on, Supabase deliberately returns a *success*
                    // response (no error) for a duplicate email too, to avoid leaking which
                    // emails are registered. The tell is an empty `identities` array — a
                    // genuinely new signup always has one identity attached.
                    const alreadyRegistered = !!data?.user && Array.isArray(data.user.identities) && data.user.identities.length === 0;
                    if (alreadyRegistered) {
                        setMode('signin');
                        emailInput.value = email;
                        passwordInput.value = '';
                        showError('An account with this email already exists — sign in instead, or use "Forgot password?" below.');
                        passwordInput.focus();
                        return;
                    }
                    if (data.session) {
                        showInfo('Account created! You\'re signed in.');
                        setTimeout(closeModal, 900);
                    } else {
                        showInfo('Account created — check your email to confirm before signing in.');
                    }
                } else {
                    const { error } = await supabaseClient.auth.signInWithPassword({ email, password });
                    if (error) {
                        if (/invalid login credentials/i.test(error.message || '')) {
                            showError('Incorrect email or password. New here? Use the Sign Up tab instead.');
                            return;
                        }
                        throw error;
                    }
                    closeModal();
                }
            } catch (err) {
                showError(err.message || 'Something went wrong — try again.');
            } finally {
                submitBtn.disabled = false;
                submitBtn.innerText = originalLabel;
            }
        });

        forgotLink?.addEventListener('click', async (e) => {
            e.preventDefault();
            if (!supabaseClient) return;
            const email = emailInput.value.trim();
            if (!email || !/^\S+@\S+\.\S+$/.test(email)) { showError('Enter your email above first, then click "Forgot password?" again.'); return; }
            const originalLabel = forgotLink.innerText;
            forgotLink.innerText = 'Sending…';
            try {
                // redirectTo must land on a page that includes this same script, since the
                // reset link carries a #type=recovery token that this file listens for below
                // (see the PASSWORD_RECOVERY branch) in order to show the "set a new password"
                // form — without that listener, the link just silently signs the user in.
                const { error } = await supabaseClient.auth.resetPasswordForEmail(email, { redirectTo: `${window.location.origin}/account.html` });
                if (error) throw error;
                showInfo('Password reset email sent — click the link in that email, then set your new password there.');
            } catch (err) {
                showError(err.message || 'Could not send reset email.');
            } finally {
                forgotLink.innerText = originalLabel;
            }
        });
    }

    // ---------- Continue with Google ----------
    // Present on the same modal markup on index.html and account.html. Google handles both
    // "sign up" and "sign in" as a single flow — Supabase creates the account on first use and
    // just signs the user in on every visit after, so this button works regardless of which
    // tab (Sign In / Sign Up) is active.
    const googleBtn = document.getElementById('auth-google-btn');
    googleBtn?.addEventListener('click', async () => {
        if (!supabaseClient) {
            document.getElementById('auth-config-warning')?.classList.remove('hidden');
            return;
        }
        googleBtn.disabled = true;
        const originalHtml = googleBtn.innerHTML;
        googleBtn.innerHTML = 'Redirecting…';
        try {
            const { error } = await supabaseClient.auth.signInWithOAuth({
                provider: 'google',
                options: { redirectTo: `${window.location.origin}${window.location.pathname}` },
            });
            if (error) throw error;
            // On success the browser is being navigated to Google right now — nothing else to do.
        } catch (err) {
            const errorEl = document.getElementById('auth-error');
            const infoEl = document.getElementById('auth-info');
            if (errorEl) {
                errorEl.innerText = err.message || 'Could not start Google sign-in. Make sure the Google provider is enabled in your Supabase project.';
                errorEl.classList.remove('hidden');
            }
            infoEl?.classList.add('hidden');
            googleBtn.disabled = false;
            googleBtn.innerHTML = originalHtml;
        }
    });

    // ---------- "Forgot password" reset flow ----------
    // Supabase's reset-password link signs the visitor in automatically (that's how it proves
    // they own the inbox) and fires a PASSWORD_RECOVERY auth event instead of the usual
    // SIGNED_IN — so the fix for "it redirects but doesn't reset" is to catch that event and
    // make the visitor actually choose a new password before treating them as a normal
    // logged-in user. This modal is injected on demand so it works on any page that loads this
    // script, without needing matching markup added to every HTML file.
    let recoveryModal = null;
    function ensureRecoveryModal() {
        if (recoveryModal) return recoveryModal;
        const wrap = document.createElement('div');
        wrap.id = 'recovery-modal';
        wrap.className = 'cw-modal-backdrop';
        wrap.innerHTML = `
            <div class="cw-modal-card" style="max-width:380px;" role="dialog" aria-modal="true" aria-label="Set a new password">
                <div class="flex items-center justify-between px-4 py-3 border-b border-gray-800 bg-[#1e222b]">
                    <span class="text-sm font-bold">Set a new password</span>
                    <button type="button" data-recovery-close aria-label="Close" class="text-gray-500 hover:text-white cursor-pointer text-lg leading-none"><i data-lucide="x" width="15" height="15" stroke-width="2.4"></i></button>
                </div>
                <div class="p-4 space-y-3">
                    <p class="text-[11px] text-gray-500 leading-relaxed">You followed a password reset link. Choose a new password below to finish resetting it.</p>
                    <div>
                        <label class="block text-[10px] font-bold uppercase tracking-wider text-gray-500 mb-1.5">New password</label>
                        <input type="password" data-recovery-password placeholder="At least 6 characters" autocomplete="new-password"
                            class="w-full bg-gray-900 border border-gray-800 rounded text-sm px-3 py-2 text-gray-200 placeholder-gray-500 focus:outline-none focus:border-[#14d38a]">
                    </div>
                    <div>
                        <label class="block text-[10px] font-bold uppercase tracking-wider text-gray-500 mb-1.5">Confirm new password</label>
                        <input type="password" data-recovery-password-confirm placeholder="Repeat password" autocomplete="new-password"
                            class="w-full bg-gray-900 border border-gray-800 rounded text-sm px-3 py-2 text-gray-200 placeholder-gray-500 focus:outline-none focus:border-[#14d38a]">
                    </div>
                    <div data-recovery-error class="hidden text-[11px] text-[#ff4d6a] bg-[#ff4d6a]/10 border border-[#ff4d6a]/20 rounded p-2"></div>
                    <div data-recovery-info class="hidden text-[11px] text-[#14d38a] bg-[#14d38a]/10 border border-[#14d38a]/20 rounded p-2"></div>
                    <button type="button" data-recovery-submit class="w-full text-sm font-bold uppercase py-2.5 rounded bg-[#14d38a] text-[#0b0e11] hover:opacity-90 transition-all cursor-pointer">Set new password</button>
                </div>
            </div>`;
        document.body.appendChild(wrap);

        const pwInput = wrap.querySelector('[data-recovery-password]');
        const pwConfirmInput = wrap.querySelector('[data-recovery-password-confirm]');
        const errEl = wrap.querySelector('[data-recovery-error]');
        const infEl = wrap.querySelector('[data-recovery-info]');
        const submit = wrap.querySelector('[data-recovery-submit]');

        function showErr(msg) { errEl.innerText = msg; errEl.classList.remove('hidden'); infEl.classList.add('hidden'); }
        function showInf(msg) { infEl.innerText = msg; infEl.classList.remove('hidden'); errEl.classList.add('hidden'); }
        function close() { wrap.classList.remove('cw-visible'); }

        wrap.querySelector('[data-recovery-close]').addEventListener('click', close);
        wrap.addEventListener('click', (e) => { if (e.target === wrap) close(); });

        submit.addEventListener('click', async () => {
            const pw = pwInput.value;
            const pw2 = pwConfirmInput.value;
            if (!pw || pw.length < 6) { showErr('Password must be at least 6 characters.'); return; }
            if (pw !== pw2) { showErr('Passwords do not match.'); return; }
            submit.disabled = true;
            const original = submit.innerText;
            submit.innerText = 'Please wait…';
            try {
                const { error } = await supabaseClient.auth.updateUser({ password: pw });
                if (error) throw error;
                showInf('Password updated — you\'re signed in with your new password.');
                pwInput.value = '';
                pwConfirmInput.value = '';
                // Strip the recovery token out of the URL so refreshing the page doesn't
                // re-open this modal.
                window.history.replaceState({}, document.title, window.location.pathname);
                setTimeout(close, 1400);
            } catch (err) {
                showErr(err.message || 'Could not update password — the reset link may have expired. Request a new one and try again.');
            } finally {
                submit.disabled = false;
                submit.innerText = original;
            }
        });

        recoveryModal = wrap;
        return wrap;
    }
    function openRecoveryModal() {
        modal?.classList.remove('cw-visible'); // don't show both modals stacked at once
        ensureRecoveryModal().classList.add('cw-visible');
    }

    // ---------- Boot: check existing session, then react to changes ----------
    if (supabaseClient) {
        supabaseClient.auth.getSession().then(({ data }) => {
            currentUser = data?.session?.user || null;
            renderHeader();
            broadcastAuth();
        });
        supabaseClient.auth.onAuthStateChange((event, session) => {
            currentUser = session?.user || null;
            renderHeader();
            broadcastAuth();
            if (event === 'PASSWORD_RECOVERY') {
                openRecoveryModal();
            }
        });
    } else {
        renderHeader();
        broadcastAuth();
    }
})();

// ==== 19-cloud-sync.js ====
// ---------- Cloud Sync (Supabase) ----------
// Mirrors a curated subset of this browser's cw_ localStorage keys to Supabase's app_state
// table so a signed-in visitor sees the same watchlist, alerts, holdings, notes, and paper
// trading account on every device. Purely additive: with no Supabase config, or while signed
// out, everything behaves exactly as before (local-only, nothing changes). Depends on
// window.cwAuth from js/17-auth.js, so this must load after it. Requires supabase-js (the
// same CDN script 17-auth.js uses) and js/00-config.js.
//
// Strategy: on sign-in, pull the remote row and compare its server-set updated_at against the
// timestamp we locally remember from our last successful push. Whichever side is newer wins
// wholesale — this is a personal single-blob sync, not a field-by-field merge, so the same
// device you used most recently is the one whose data survives. Good enough for a solo
// dashboard; a person actively editing on two devices at once isn't the target use case.
// After the initial sync, a lightweight poll (comparing a JSON snapshot of the synced keys)
// detects local changes and pushes them, debounced, without requiring every other module to be
// instrumented with sync calls.

(function () {
    // Deliberately short allowlist. Excluded on purpose:
    //   - cw_groq_api_key: a personal secret, must never leave this browser.
    //   - cw_ai_history / cw_alert_history: unbounded local scrollback, not core account state.
    const SYNCED_KEYS = [
        'cw_watchlist', 'cw_alerts', 'cw_holdings', 'cw_futures_positions', 'cw_notes',
        'cw_paper_cash', 'cw_paper_deposited', 'cw_paper_equity_curve', 'cw_paper_holdings',
        'cw_paper_orders', 'cw_paper_trades', 'cw_accent', 'cw_sound_enabled', 'cw_last_selection',
    ];

    const META_KEY = 'cw_sync_meta'; // { lastPushedAt } — an ISO timestamp from the SERVER, not this browser's clock
    const POLL_MS = 4000;
    const PUSH_DEBOUNCE_MS = 2500;

    let client = null;
    let userId = null;
    let pushTimer = null;
    let pollTimer = null;
    let lastLocalSnapshot = null;
    let status = 'idle'; // idle | syncing | synced | error
    const statusListeners = [];

    function setStatus(next) {
        status = next;
        statusListeners.forEach((cb) => { try { cb(status); } catch { /* listener's problem, not ours */ } });
        renderStatusUI();
    }

    function readMeta() {
        try { return JSON.parse(localStorage.getItem(META_KEY) || '{}'); } catch { return {}; }
    }
    function writeMeta(meta) {
        try { localStorage.setItem(META_KEY, JSON.stringify(meta)); } catch { /* storage full/unavailable — sync just retries next cycle */ }
    }

    function snapshotLocal() {
        const out = {};
        for (const k of SYNCED_KEYS) {
            const v = localStorage.getItem(k);
            if (v !== null) out[k] = v;
        }
        return out;
    }

    function applyRemote(state) {
        if (!state || typeof state !== 'object') return;
        const before = JSON.stringify(snapshotLocal());
        for (const k of SYNCED_KEYS) {
            if (Object.prototype.hasOwnProperty.call(state, k)) {
                try { localStorage.setItem(k, state[k]); } catch { /* ignore individual key write failures */ }
            }
        }
        const after = JSON.stringify(snapshotLocal());
        lastLocalSnapshot = after;
        // Other modules (state/portfolio/paper-trading/alerts) read localStorage once at their
        // own load time and cache it in memory with no shared re-render hook — dispatch this for
        // any listener that wants it, and also do a one-time reload when the data we just applied
        // is actually different from what was already on this device (e.g. switching devices, or
        // clicking "sync now" after changes elsewhere). Same-device re-syncs where nothing changed
        // never hit this path.
        document.dispatchEvent(new CustomEvent('cw:cloud-sync-applied'));
        if (before !== after && document.visibilityState !== 'hidden') {
            setTimeout(() => window.location.reload(), 60);
        }
    }

    async function pushNow() {
        if (!client || !userId) return;
        setStatus('syncing');
        const state = snapshotLocal();
        try {
            const { data, error } = await client
                .from('app_state')
                .upsert({ user_id: userId, state }, { onConflict: 'user_id' })
                .select('updated_at')
                .single();
            if (error) throw error;
            writeMeta({ lastPushedAt: data?.updated_at || new Date().toISOString() });
            lastLocalSnapshot = JSON.stringify(state);
            setStatus('synced');
        } catch (err) {
            console.error('[CryptoBolt] Cloud sync push failed:', err?.message || err);
            setStatus('error');
        }
    }

    function schedulePush() {
        if (pushTimer) clearTimeout(pushTimer);
        pushTimer = setTimeout(pushNow, PUSH_DEBOUNCE_MS);
    }

    function flushPendingPush() {
        if (pushTimer) {
            clearTimeout(pushTimer);
            pushTimer = null;
            pushNow();
        }
    }

    async function pullAndMerge() {
        if (!client || !userId) return;
        setStatus('syncing');
        try {
            const { data, error } = await client
                .from('app_state')
                .select('state, updated_at')
                .eq('user_id', userId)
                .maybeSingle();
            if (error) throw error;

            const meta = readMeta();
            const hasRemoteData = data && data.state && Object.keys(data.state).length > 0;
            const remoteIsNewer = hasRemoteData && (!meta.lastPushedAt || new Date(data.updated_at) > new Date(meta.lastPushedAt));
            const localHasAnyData = SYNCED_KEYS.some((k) => localStorage.getItem(k) !== null);

            if (hasRemoteData && (remoteIsNewer || !localHasAnyData)) {
                applyRemote(data.state);
                writeMeta({ lastPushedAt: data.updated_at });
                setStatus('synced');
                return;
            }
            // No remote row yet, or this device's local copy is the newer/authoritative one.
            await pushNow();
        } catch (err) {
            console.error('[CryptoBolt] Cloud sync pull failed:', err?.message || err);
            setStatus('error');
        }
    }

    function startPolling() {
        stopPolling();
        lastLocalSnapshot = JSON.stringify(snapshotLocal());
        pollTimer = setInterval(() => {
            const snap = JSON.stringify(snapshotLocal());
            if (snap !== lastLocalSnapshot) {
                lastLocalSnapshot = snap;
                schedulePush();
            }
        }, POLL_MS);
    }
    function stopPolling() {
        if (pollTimer) clearInterval(pollTimer);
        pollTimer = null;
        if (pushTimer) clearTimeout(pushTimer);
        pushTimer = null;
    }

    // Flush any pending debounced push immediately when the tab is about to lose focus/close,
    // so a change made seconds before navigating away isn't lost.
    document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'hidden') flushPendingPush();
    });

    // ---------- Optional status UI (present on pages that include the markup; safe no-op otherwise) ----------
    function renderStatusUI() {
        const wrap = document.getElementById('cloud-sync-status');
        const dot = document.getElementById('cloud-sync-dot');
        const label = document.getElementById('cloud-sync-label');
        if (!wrap) return;
        if (!userId) { wrap.classList.add('hidden'); wrap.classList.remove('flex'); return; }
        wrap.classList.remove('hidden');
        wrap.classList.add('flex');
        if (dot) dot.className = `status-dot ${status === 'error' ? 'status-error' : status === 'syncing' ? 'status-connecting' : 'status-live'}`;
        if (label) label.innerText = status === 'error' ? 'sync error' : status === 'syncing' ? 'syncing…' : 'synced';
        wrap.title = status === 'error'
            ? 'Cloud sync failed — click to retry'
            : status === 'syncing'
                ? 'Syncing your watchlist, alerts, holdings & paper account…'
                : 'Your watchlist, alerts, holdings & paper account are synced to your account. Click to sync now.';
    }

    document.getElementById && document.addEventListener('DOMContentLoaded', () => {
        const wrap = document.getElementById('cloud-sync-status');
        wrap?.addEventListener('click', () => { if (userId) pullAndMerge(); });
    });

    window.cwCloudSync = {
        getStatus: () => status,
        onStatusChange: (cb) => statusListeners.push(cb),
        syncNow: () => (userId ? pullAndMerge() : Promise.resolve()),
    };

    function boot() {
        if (typeof window.cwAuth === 'undefined') {
            console.info('[CryptoBolt] Cloud sync disabled — js/17-auth.js did not load before js/19-cloud-sync.js.');
            return;
        }
        window.cwAuth.onChange(async (user, configured) => {
            client = configured ? window.cwAuth.getClient() : null;
            if (user && client) {
                userId = user.id;
                await pullAndMerge();
                startPolling();
            } else {
                userId = null;
                stopPolling();
                setStatus('idle');
            }
        });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', boot);
    } else {
        boot();
    }
})();


// ==== 18-account.js ====
// ---------- My Account page logic ----------
// Reads the signed-in visitor's real purchase history from Supabase's `purchases` table and
// renders holdings + P&L + order history. Buy/Sell redirects to Binance in a new tab (see
// js/14-buy-sell-redirect.js) with no way to report back what happened, so the "+ Log Trade"
// form further down in this file is the row-source for `purchases` by default — a manual
// receipt entry, not an automated import. A site owner can still wire up their own
// provider-specific integration (an exchange webhook, etc.) on top of the same table if they
// want automatic logging later. This page is entirely dependent on js/17-auth.js having
// already set up window.cwAuth — it reacts to the 'cw:auth' event rather than assuming a load
// order.

(function () {
    function fmtUsd(n, opts) {
        if (n === null || n === undefined || isNaN(n)) return '--';
        return `$${n.toLocaleString(undefined, opts || { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
    }
    function fmtSigned(n) {
        if (n === null || n === undefined || isNaN(n)) return '--';
        return `${n >= 0 ? '+' : ''}${fmtUsd(n)}`;
    }
    function fmtQty(n) {
        if (n === null || n === undefined || isNaN(n)) return '--';
        return n.toLocaleString(undefined, { maximumFractionDigits: 8 });
    }
    function priceFmt(price) {
        return price < 1 ? { minimumFractionDigits: 4, maximumFractionDigits: 6 } : { minimumFractionDigits: 2, maximumFractionDigits: 2 };
    }
    function pnlColorClass(n) {
        if (n === null || n === undefined || isNaN(n) || n === 0) return 'text-gray-400';
        return n > 0 ? 'text-[#14d38a]' : 'text-[#ff4d6a]';
    }
    const ESCAPE_HTML_MAP = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
    function escapeHtml(str) {
        if (str === null || str === undefined) return '';
        return String(str).replace(/[&<>"']/g, (ch) => ESCAPE_HTML_MAP[ch]);
    }
    function showToast(message, tone = 'info') {
        const toneMap = { success: { color: 'var(--cw-green)', icon: '<i data-lucide="check" width="14" height="14" stroke-width="2.5"></i>' }, error: { color: 'var(--cw-red)', icon: '<i data-lucide="x" width="14" height="14" stroke-width="2.5"></i>' }, info: { color: 'var(--cw-cyan)', icon: '<i data-lucide="info" width="14" height="14" stroke-width="2.3"></i>' } };
        const { color, icon } = toneMap[tone] || toneMap.info;
        const el = document.createElement('div');
        el.className = 'toast-enter cw-toast rounded-lg pr-4 py-2.5 text-xs shadow-2xl max-w-xs border border-gray-800';
        el.style.setProperty('--cw-tone', color);
        el.innerHTML = `<span class="cw-toast-icon text-[13px]">${icon}</span><span class="font-mono leading-snug pt-px" style="color:${color}">${escapeHtml(message)}</span>`;
        document.getElementById('toast-container').appendChild(el);
        setTimeout(() => { el.style.transition = 'opacity 0.4s, transform 0.4s'; el.style.opacity = '0'; el.style.transform = 'translateX(16px)'; setTimeout(() => el.remove(), 400); }, 4500);
    }

    const signedOutPanel = document.getElementById('signed-out-panel');
    const notConfiguredPanel = document.getElementById('not-configured-panel');
    const dashboard = document.getElementById('account-dashboard');

    document.getElementById('signed-out-signin-btn')?.addEventListener('click', () => {
        document.getElementById('auth-open-btn')?.click();
    });

    let purchases = [];
    let priceMap = {};

    async function fetchWithTimeout(url, ms = 9000) {
        const ctrl = new AbortController();
        const t = setTimeout(() => ctrl.abort(), ms);
        try { return await fetch(url, { signal: ctrl.signal }); } finally { clearTimeout(t); }
    }

    async function fetchLivePrices(symbols) {
        if (symbols.length === 0) return;
        try {
            const pairs = symbols.map(s => `${s}USDT`);
            const symbolsParam = encodeURIComponent(JSON.stringify(pairs));
            const res = await fetchWithTimeout(`https://api.binance.com/api/v3/ticker/price?symbols=${symbolsParam}`);
            if (!res.ok) throw new Error(`HTTP ${res.status}`);
            const arr = await res.json();
            if (Array.isArray(arr)) {
                arr.forEach(row => {
                    if (row.symbol && row.symbol.endsWith('USDT')) priceMap[row.symbol.replace('USDT', '')] = parseFloat(row.price) || 0;
                });
            }
        } catch (err) {
            console.warn('[CryptoBolt] Live price fetch failed:', err.message);
        }
    }

    function computeHoldings() {
        // Aggregate buy/sell rows per symbol with a running weighted-average cost basis, in
        // chronological order, so realized P&L on sells is computed against the correct avgCost.
        const bySymbol = {}; // symbol -> { qty, avgCost, spent, sold, realized }
        let totalSpent = 0, totalSold = 0, totalRealized = 0;

        const chronological = purchases.slice().sort((a, b) => new Date(a.created_at) - new Date(b.created_at));
        chronological.forEach(p => {
            const sym = p.symbol;
            if (!bySymbol[sym]) bySymbol[sym] = { qty: 0, avgCost: 0, spent: 0, sold: 0, realized: 0 };
            const h = bySymbol[sym];
            const qty = Number(p.crypto_amount) || 0;
            const fiat = Number(p.fiat_amount) || 0;
            if (p.side === 'buy') {
                const newQty = h.qty + qty;
                h.avgCost = newQty > 0 ? (h.qty * h.avgCost + fiat) / newQty : 0;
                h.qty = newQty;
                h.spent += fiat;
                totalSpent += fiat;
            } else {
                const sellQty = Math.min(qty, h.qty);
                const costBasis = sellQty * h.avgCost;
                const realized = fiat - costBasis;
                h.qty = Math.max(0, h.qty - qty);
                h.sold += fiat;
                h.realized += realized;
                totalSold += fiat;
                totalRealized += realized;
            }
        });
        return { bySymbol, totalSpent, totalSold, totalRealized };
    }

    function render() {
        const { bySymbol, totalSpent, totalSold, totalRealized } = computeHoldings();
        const activeSymbols = Object.entries(bySymbol).filter(([, h]) => h.qty > 1e-9);

        let holdingsValue = 0, unrealized = 0;
        activeSymbols.forEach(([sym, h]) => {
            const price = priceMap[sym] || 0;
            holdingsValue += price * h.qty;
            unrealized += (price - h.avgCost) * h.qty;
        });

        document.getElementById('stat-value').innerText = fmtUsd(holdingsValue);
        const totalPnl = unrealized + totalRealized;
        const pnlEl = document.getElementById('stat-pnl');
        pnlEl.innerText = fmtSigned(totalPnl);
        pnlEl.className = `text-sm font-mono font-bold ${pnlColorClass(totalPnl)}`;
        document.getElementById('stat-spent').innerText = fmtUsd(totalSpent);
        document.getElementById('stat-sold').innerText = fmtUsd(totalSold);
        const unrealEl = document.getElementById('stat-unrealized');
        unrealEl.innerText = fmtSigned(unrealized); unrealEl.className = `text-sm font-mono font-bold ${pnlColorClass(unrealized)}`;
        const realEl = document.getElementById('stat-realized');
        realEl.innerText = fmtSigned(totalRealized); realEl.className = `text-sm font-mono font-bold ${pnlColorClass(totalRealized)}`;
        document.getElementById('stat-assets').innerText = activeSymbols.length;
        document.getElementById('stat-orders').innerText = purchases.length;

        const holdingsBody = document.getElementById('holdings-rows');
        if (activeSymbols.length === 0) {
            holdingsBody.innerHTML = `<tr><td colspan="6" class="py-8 text-center text-gray-600 text-[11px]">No holdings yet — buy some crypto from the terminal.</td></tr>`;
        } else {
            holdingsBody.innerHTML = activeSymbols
                .sort((a, b) => (priceMap[b[0]] * b[1].qty) - (priceMap[a[0]] * a[1].qty))
                .map(([sym, h]) => {
                    const price = priceMap[sym] || 0;
                    const value = price * h.qty;
                    const pnl = (price - h.avgCost) * h.qty;
                    return `
                        <tr class="hover:bg-gray-800/40 transition-colors">
                            <td class="py-2 px-3 font-bold text-white">${escapeHtml(sym)}</td>
                            <td class="py-2 px-3 text-right text-gray-300">${fmtQty(h.qty)}</td>
                            <td class="py-2 px-3 text-right text-gray-400">${fmtUsd(h.avgCost, priceFmt(h.avgCost))}</td>
                            <td class="py-2 px-3 text-right text-gray-300">${price ? fmtUsd(price, priceFmt(price)) : '<span class="text-gray-600">--</span>'}</td>
                            <td class="py-2 px-3 text-right text-gray-200">${fmtUsd(value)}</td>
                            <td class="py-2 px-3 text-right ${pnlColorClass(pnl)}">${fmtSigned(pnl)}</td>
                        </tr>`;
                }).join('');
        }

        const ordersBody = document.getElementById('orders-rows');
        if (purchases.length === 0) {
            ordersBody.innerHTML = `<tr><td colspan="6" class="py-8 text-center text-gray-600 text-[11px]">No orders yet — buy some crypto from the terminal to see it here.</td></tr>`;
        } else {
            ordersBody.innerHTML = purchases.slice().sort((a, b) => new Date(b.created_at) - new Date(a.created_at)).map(p => {
                const sideColor = p.side === 'buy' ? 'text-[#14d38a] bg-[#14d38a]/10 border-[#14d38a]/30' : 'text-[#ff4d6a] bg-[#ff4d6a]/10 border-[#ff4d6a]/30';
                const price = Number(p.price_usd) || (Number(p.fiat_amount) / Number(p.crypto_amount));
                return `
                    <tr class="hover:bg-gray-800/40 transition-colors">
                        <td class="py-2 px-3 text-gray-500">${new Date(p.created_at).toLocaleString()}</td>
                        <td class="py-2 px-3 font-bold text-white">${escapeHtml(p.symbol)}</td>
                        <td class="py-2 px-3"><span class="text-[9px] font-bold uppercase px-1.5 py-0.5 rounded border ${sideColor}">${escapeHtml(p.side)}</span></td>
                        <td class="py-2 px-3 text-right text-gray-300">${fmtQty(Number(p.crypto_amount))}</td>
                        <td class="py-2 px-3 text-right text-gray-300">${fmtUsd(Number(p.fiat_amount))}</td>
                        <td class="py-2 px-3 text-right text-gray-400">${fmtUsd(price, priceFmt(price))}</td>
                    </tr>`;
            }).join('');
        }
    }

    async function loadPurchases() {
        const client = window.cwAuth?.getClient?.();
        const user = window.cwAuth?.getUser?.();
        if (!client || !user) return;
        const { data, error } = await client
            .from('purchases')
            .select('*')
            .order('created_at', { ascending: false });
        if (error) {
            showToast('Could not load your purchase history — try refreshing.', 'error');
            console.error('[CryptoBolt] purchases fetch error:', error.message);
            return;
        }
        purchases = data || [];
        const symbols = Array.from(new Set(purchases.map(p => p.symbol)));
        await fetchLivePrices(symbols);
        render();
    }

    document.getElementById('refresh-btn')?.addEventListener('click', () => {
        loadPurchases();
        showToast('Refreshed.', 'success');
    });

    // ---------- Manual trade log (see account.html for the form + supabase/schema.sql for the
    // `purchases` table + RLS policy this insert relies on) ----------
    const logTradeToggleBtn = document.getElementById('log-trade-toggle-btn');
    const logTradeForm = document.getElementById('log-trade-form');
    const logTradeSubmitBtn = document.getElementById('log-trade-submit-btn');

    logTradeToggleBtn?.addEventListener('click', () => {
        const willShow = logTradeForm.classList.contains('hidden');
        logTradeForm.classList.toggle('hidden', !willShow);
        logTradeToggleBtn.setAttribute('aria-expanded', String(willShow));
        if (willShow) {
            // Default the date field to "now" each time the form is opened, in the visitor's
            // own local time (datetime-local has no timezone of its own).
            const dateInput = document.getElementById('log-trade-date');
            if (dateInput && !dateInput.value) {
                const now = new Date(Date.now() - new Date().getTimezoneOffset() * 60000);
                dateInput.value = now.toISOString().slice(0, 16);
            }
            document.getElementById('log-trade-symbol')?.focus();
        }
    });

    logTradeForm?.addEventListener('submit', async (e) => {
        e.preventDefault();
        const client = window.cwAuth?.getClient?.();
        const user = window.cwAuth?.getUser?.();
        if (!client || !user) { showToast('You need to be signed in to log a trade.', 'error'); return; }

        const side = document.getElementById('log-trade-side').value;
        const symbol = document.getElementById('log-trade-symbol').value.trim().toUpperCase();
        const qty = parseFloat(document.getElementById('log-trade-qty').value);
        const fiat = parseFloat(document.getElementById('log-trade-fiat').value);
        const dateVal = document.getElementById('log-trade-date').value;

        if (!symbol || !/^[A-Z0-9]{1,15}$/.test(symbol)) { showToast('Enter a valid asset symbol, e.g. BTC.', 'error'); return; }
        if (!Number.isFinite(qty) || qty <= 0) { showToast('Enter a quantity greater than 0.', 'error'); return; }
        if (!Number.isFinite(fiat) || fiat <= 0) { showToast('Enter a USD amount greater than 0.', 'error'); return; }

        const createdAt = dateVal ? new Date(dateVal).toISOString() : new Date().toISOString();

        logTradeSubmitBtn.disabled = true;
        const originalLabel = logTradeSubmitBtn.innerText;
        logTradeSubmitBtn.innerText = 'Saving…';
        try {
            const { error } = await client.from('purchases').insert({
                user_id: user.id,
                side,
                symbol,
                crypto_amount: qty,
                fiat_amount: fiat,
                fiat_currency: 'USD',
                price_usd: fiat / qty,
                provider: 'manual',
                status: 'completed',
                created_at: createdAt,
            });
            if (error) {
                showToast(error.message || 'Could not save that trade.', 'error');
                console.error('[CryptoBolt] manual trade log insert error:', error.message);
                return;
            }
            showToast(`Logged ${side} of ${fmtQty(qty)} ${symbol}.`, 'success');
            logTradeForm.reset();
            logTradeForm.classList.add('hidden');
            logTradeToggleBtn.setAttribute('aria-expanded', 'false');
            await loadPurchases();
        } catch (err) {
            showToast(err.message || 'Could not save that trade.', 'error');
        } finally {
            logTradeSubmitBtn.disabled = false;
            logTradeSubmitBtn.innerText = originalLabel;
        }
    });

    // ---------- Telegram alert delivery ----------
    // Chat id lives in its own table (notification_settings), not `profiles`, because
    // `profiles` has a public "Anyone can view usernames" SELECT policy — see
    // supabase/schema.sql. The card itself is hidden entirely on deployments that haven't set
    // TELEGRAM_BOT_TOKEN server-side (checked via GET /api/telegram/configured), same "stay
    // quiet if not configured" pattern as js/23-push-alerts.js.
    function resolveApiUrl(path) {
        const base = (typeof CW_CONFIG !== 'undefined' && CW_CONFIG.apiBaseUrl ? CW_CONFIG.apiBaseUrl : '').replace(/\/$/, '');
        return /^https?:\/\//i.test(path) ? path : `${base}${path}`;
    }

    const telegramCard = document.getElementById('telegram-chat-id-input')?.closest('.cw-card-interactive');
    const telegramInput = document.getElementById('telegram-chat-id-input');
    const telegramSaveBtn = document.getElementById('telegram-save-btn');
    const telegramRemoveBtn = document.getElementById('telegram-remove-btn');
    const telegramMsg = document.getElementById('telegram-msg');

    function showTelegramMsg(msg, tone) {
        if (!telegramMsg) return;
        telegramMsg.innerText = msg;
        telegramMsg.className = `text-[11px] px-6 pb-3 ${tone === 'error' ? 'text-[#ff4d6a]' : 'text-[#14d38a]'}`;
        telegramMsg.classList.remove('hidden');
    }

    async function loadTelegramLink() {
        if (!telegramCard) return;
        try {
            const res = await fetch(resolveApiUrl('/api/telegram/configured'));
            const cfg = res.ok ? await res.json() : { configured: false };
            if (!cfg.configured) { telegramCard.classList.add('hidden'); return; }
        } catch {
            telegramCard.classList.add('hidden'); // network hiccup or no backend at all — stay quiet, same as push
            return;
        }
        telegramCard.classList.remove('hidden');

        const client = window.cwAuth?.getClient?.();
        const user = window.cwAuth?.getUser?.();
        if (!client || !user) return;
        const { data, error } = await client
            .from('notification_settings')
            .select('telegram_chat_id')
            .eq('user_id', user.id)
            .maybeSingle();
        if (!error && data?.telegram_chat_id) {
            telegramInput.value = data.telegram_chat_id;
            telegramRemoveBtn.classList.remove('hidden');
        }
    }

    telegramSaveBtn?.addEventListener('click', async () => {
        const client = window.cwAuth?.getClient?.();
        const user = window.cwAuth?.getUser?.();
        if (!client || !user || !telegramInput) return;
        const chatId = telegramInput.value.trim();
        if (!/^-?\d{4,15}$/.test(chatId)) {
            showTelegramMsg('Enter the numeric chat id Telegram gave you (see the instructions above).', 'error');
            return;
        }
        telegramSaveBtn.disabled = true;
        const original2 = telegramSaveBtn.innerText;
        telegramSaveBtn.innerText = 'Saving…';
        try {
            const { error } = await client
                .from('notification_settings')
                .upsert({ user_id: user.id, telegram_chat_id: chatId, updated_at: new Date().toISOString() });
            if (error) { showTelegramMsg(error.message || 'Could not link Telegram.', 'error'); return; }
            showTelegramMsg("Telegram linked — you'll get alerts there even with every tab closed.", 'success');
            telegramRemoveBtn.classList.remove('hidden');
        } catch (err) {
            showTelegramMsg(err.message || 'Could not link Telegram.', 'error');
        } finally {
            telegramSaveBtn.disabled = false;
            telegramSaveBtn.innerText = original2;
        }
    });

    telegramRemoveBtn?.addEventListener('click', async () => {
        const client = window.cwAuth?.getClient?.();
        const user = window.cwAuth?.getUser?.();
        if (!client || !user) return;
        try {
            const { error } = await client
                .from('notification_settings')
                .update({ telegram_chat_id: null })
                .eq('user_id', user.id);
            if (error) { showTelegramMsg(error.message || 'Could not unlink Telegram.', 'error'); return; }
            telegramInput.value = '';
            telegramRemoveBtn.classList.add('hidden');
            showTelegramMsg('Telegram unlinked.', 'success');
        } catch (err) {
            showTelegramMsg(err.message || 'Could not unlink Telegram.', 'error');
        }
    });

    // ---------- Leaderboard username ----------
    const USERNAME_RE = /^[A-Za-z0-9_]{3,20}$/;
    const usernameInput = document.getElementById('username-input');
    const usernameSaveBtn = document.getElementById('username-save-btn');
    const usernameMsg = document.getElementById('username-msg');

    function showUsernameMsg(msg, tone) {
        if (!usernameMsg) return;
        usernameMsg.innerText = msg;
        usernameMsg.className = `text-[11px] px-6 pb-3 ${tone === 'error' ? 'text-[#ff4d6a]' : 'text-[#14d38a]'}`;
        usernameMsg.classList.remove('hidden');
    }

    async function loadUsername() {
        const client = window.cwAuth?.getClient?.();
        const user = window.cwAuth?.getUser?.();
        if (!client || !user || !usernameInput) return;
        const { data, error } = await client.from('profiles').select('username').eq('id', user.id).maybeSingle();
        if (!error && data?.username) usernameInput.value = data.username;
    }

    usernameSaveBtn?.addEventListener('click', async () => {
        const client = window.cwAuth?.getClient?.();
        const user = window.cwAuth?.getUser?.();
        if (!client || !user || !usernameInput) return;
        const next = usernameInput.value.trim();
        if (!USERNAME_RE.test(next)) {
            showUsernameMsg('Username must be 3-20 characters — letters, numbers, and underscores only.', 'error');
            return;
        }
        usernameSaveBtn.disabled = true;
        const original = usernameSaveBtn.innerText;
        usernameSaveBtn.innerText = 'Saving…';
        try {
            let { data: updated, error } = await client.from('profiles').update({ username: next }).eq('id', user.id).select('id');
            // An UPDATE that matches no row succeeds silently. Accounts created before the profiles
            // trigger existed have no row yet, so create it (needs the insert policy in supabase/fix-profiles.sql).
            if (!error && (!updated || updated.length === 0)) {
                ({ error } = await client.from('profiles').insert({ id: user.id, username: next }));
            }
            if (error) {
                if (/duplicate|already exists|unique/i.test(error.message || '')) {
                    showUsernameMsg('That username is already taken — try another.', 'error');
                } else {
                    showUsernameMsg(error.message || 'Could not save username.', 'error');
                }
                return;
            }
            showUsernameMsg('Username saved.', 'success');
            window.dispatchEvent(new CustomEvent('cw-username-saved'));
        } catch (err) {
            showUsernameMsg(err.message || 'Could not save username.', 'error');
        } finally {
            usernameSaveBtn.disabled = false;
            usernameSaveBtn.innerText = original;
        }
    });

    function handleAuthChange(user, configured) {
        if (!configured) {
            notConfiguredPanel.classList.remove('hidden');
            signedOutPanel.classList.add('hidden');
            dashboard.classList.add('hidden');
            return;
        }
        notConfiguredPanel.classList.add('hidden');
        if (user) {
            signedOutPanel.classList.add('hidden');
            dashboard.classList.remove('hidden');
            const emailEl = document.getElementById('auth-user-email');
            if (emailEl) emailEl.innerText = user.email || '';
            loadPurchases();
            loadUsername();
            loadTelegramLink();
        } else {
            dashboard.classList.add('hidden');
            signedOutPanel.classList.remove('hidden');
        }
    }

    // window.cwAuth is guaranteed to exist by the time this script runs (js/17-auth.js loads
    // first and defines it synchronously), so this registration itself can never race — and
    // onChange fires immediately if the initial session check already resolved.
    window.cwAuth.onChange(handleAuthChange);
})();

// ==== 24-referrals.js ====
// ---------- Referrals: "Invite friends, both of you get $500 virtual cash" ----------
// Runs on every page that includes it (index.html, trade.html, account.html). Three jobs,
// each independent of the others so this works no matter which subset of markup a page has:
//
//   1. On ANY page: if the URL has ?ref=USERNAME, remember it in localStorage so it survives
//      navigating to wherever the visitor actually signs up. js/17-auth.js reads it back via
//      window.cwReferral.getStoredRefCode() and sends it along with signUp() — a database
//      trigger (handle_new_user(), see supabase/schema.sql) does the actual bookkeeping.
//   2. On account.html (if #referral-link-input is present): shows the signed-in visitor their
//      own shareable link and how many friends have signed up through it.
//   3. On trade.html (if window.cwPaperTrading is present): once signed in, claims any
//      outstanding referral bonus (server-side, via claim_referral_bonus() — safe to call
//      repeatedly, it only ever pays out once per referral) and deposits it as virtual cash.
//
// Depends on window.cwAuth (js/17-auth.js, must load first) and, for job 3, on
// window.cwPaperTrading (js/16-paper-trading.js, must load first).

(function () {
    const REF_STORAGE_KEY = 'cw_referral_code';
    const USERNAME_RE = /^[A-Za-z0-9_]{3,20}$/;

    // ---------- Job 1: capture ?ref= from the URL (runs unconditionally) ----------
    try {
        const params = new URLSearchParams(window.location.search);
        const ref = (params.get('ref') || '').trim();
        // Never overwrite an already-stored code — first link a visitor clicked wins, so
        // clicking their own trade.html link later (e.g. after signing in) can't stomp it.
        if (ref && USERNAME_RE.test(ref) && !localStorage.getItem(REF_STORAGE_KEY)) {
            localStorage.setItem(REF_STORAGE_KEY, ref);
        }
    } catch (err) {
        // Storage can throw in locked-down/private-browsing contexts — referral capture just
        // silently no-ops, it's not essential to the page working.
    }

    window.cwReferral = {
        getStoredRefCode: () => {
            try { return localStorage.getItem(REF_STORAGE_KEY) || ''; } catch { return ''; }
        },
    };

    if (!window.cwAuth) return; // page doesn't load js/17-auth.js — nothing else to do here

    function showToast(message, tone = 'info') {
        const container = document.getElementById('toast-container');
        if (!container) return;
        const toneMap = { success: { color: 'var(--cw-green)', icon: '<i data-lucide="check" width="14" height="14" stroke-width="2.5"></i>' }, error: { color: 'var(--cw-red)', icon: '<i data-lucide="x" width="14" height="14" stroke-width="2.5"></i>' }, info: { color: 'var(--cw-cyan)', icon: '<i data-lucide="info" width="14" height="14" stroke-width="2.3"></i>' } };
        const { color, icon } = toneMap[tone] || toneMap.info;
        const el = document.createElement('div');
        el.className = 'toast-enter cw-toast rounded-lg pr-4 py-2.5 text-xs shadow-2xl max-w-xs border border-gray-800';
        el.style.setProperty('--cw-tone', color);
        el.innerText = ''; // set via child spans below (avoids re-parsing `message` as HTML)
        const iconSpan = document.createElement('span');
        iconSpan.className = 'cw-toast-icon text-[13px]';
        iconSpan.innerHTML = icon; // icon is always a fixed string from toneMap above, never user input
        const msgSpan = document.createElement('span');
        msgSpan.className = 'font-mono leading-snug pt-px';
        msgSpan.style.color = color;
        msgSpan.innerText = message;
        el.appendChild(iconSpan);
        el.appendChild(msgSpan);
        container.appendChild(el);
        setTimeout(() => { el.style.transition = 'opacity 0.4s, transform 0.4s'; el.style.opacity = '0'; el.style.transform = 'translateX(16px)'; setTimeout(() => el.remove(), 400); }, 5500);
    }

    function fmtUsd(n) {
        return `$${Number(n).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
    }

    // ---------- Job 2: account.html "Invite & Earn" card ----------
    const linkInput = document.getElementById('referral-link-input');
    const copyBtn = document.getElementById('referral-copy-btn');
    const countEl = document.getElementById('referral-count');
    const msgEl = document.getElementById('referral-msg');

    if (linkInput && copyBtn) {
        function showInviteMsg(text, tone) {
            if (!msgEl) return;
            msgEl.innerText = text;
            msgEl.style.color = tone === 'error' ? 'var(--cw-red)' : 'var(--cw-green)';
            msgEl.classList.remove('hidden');
        }

        let needsUsername = false;
        async function renderInviteCard(user) {
            needsUsername = false;
            const client = window.cwAuth.getClient();
            if (!user || !client) {
                linkInput.value = '';
                linkInput.placeholder = 'Sign in to get your invite link';
                if (countEl) countEl.textContent = '0';
                return;
            }
            try {
                const { data: profile } = await client.from('profiles').select('username').eq('id', user.id).maybeSingle();
                if (profile?.username) {
                    linkInput.value = `${window.location.origin}/trade.html?ref=${encodeURIComponent(profile.username)}`;
                    linkInput.placeholder = '';
                    msgEl?.classList.add('hidden');
                } else {
                    // Signed in, but no username yet — the invite link is built from it.
                    linkInput.value = '';
                    linkInput.placeholder = 'Set your leaderboard username above to get your invite link';
                    needsUsername = true;
                }
            } catch (err) {
                console.error('[CryptoBolt] Failed to load referral link:', err.message);
            }
            try {
                const { count } = await client.from('referrals').select('id', { count: 'exact', head: true }).eq('referrer_id', user.id);
                if (countEl) countEl.textContent = String(count || 0);
            } catch (err) {
                console.error('[CryptoBolt] Failed to load referral count:', err.message);
            }
        }

        window.cwAuth.onChange((user) => { renderInviteCard(user); });
        // account.js fires this after a successful username save so the link appears immediately.
        window.addEventListener('cw-username-saved', () => { renderInviteCard(window.cwAuth.getUser ? window.cwAuth.getUser() : null); });

        copyBtn.addEventListener('click', async () => {
            if (!linkInput.value) {
                showInviteMsg(needsUsername ? 'Save a leaderboard username above first — your invite link is built from it.' : 'Sign in first to get your personal invite link.', 'error');
                return;
            }
            try {
                await navigator.clipboard.writeText(linkInput.value);
                showInviteMsg('Link copied — share it anywhere!', 'success');
            } catch (err) {
                linkInput.removeAttribute('readonly');
                linkInput.select();
                document.execCommand('copy');
                linkInput.setAttribute('readonly', 'true');
                showInviteMsg('Link copied!', 'success');
            }
        });
    }

    // ---------- Job 3: trade.html — claim any outstanding bonus ----------
    if (window.cwPaperTrading && typeof window.cwPaperTrading.addBonusCash === 'function') {
        let claimed = false; // guards against onChange firing more than once per page load
        window.cwAuth.onChange(async (user, configured) => {
            if (!user || !configured || claimed) return;
            claimed = true;
            const client = window.cwAuth.getClient();
            if (!client) return;
            try {
                const { data, error } = await client.rpc('claim_referral_bonus');
                if (error) throw error;
                const amount = Number(data) || 0;
                if (amount > 0) {
                    window.cwPaperTrading.addBonusCash(amount);
                    showToast(`Referral bonus: +${fmtUsd(amount)} virtual cash added to your account!`, 'success');
                }
            } catch (err) {
                console.error('[CryptoBolt] Failed to claim referral bonus:', err.message);
                claimed = false; // allow a retry on the next auth event (e.g. token refresh)
            }
        });
    }
})();

// ==== 20-scroll-reveal.js ====
// ---------- Scroll-reveal for cards (shared across every bundle) ----------
// Cards marked `.cw-reveal` fade/slide into view the first time they cross into the viewport,
// then stay revealed (no re-hiding on scroll-out) — a common, tasteful modern-dashboard touch.
// This used to live inline in 12-events-init.js, which only ships in bundle-home.js — any page
// whose bundle didn't include that file (trade.html, account.html, ...) rendered every
// `.cw-reveal` card permanently stuck at opacity:0 (see css/styles.css), i.e. a blank page below
// the header. Pulled out into its own tiny module, included in every bundle, so that can't
// happen again regardless of which other modules a given page needs.
(function setupScrollReveal() {
    const cards = document.querySelectorAll('.cw-reveal');
    if (!('IntersectionObserver' in window)) {
        cards.forEach(el => el.classList.add('cw-in-view'));
        return;
    }

    // Cards already sitting in the viewport at page-load time would otherwise still
    // fade/slide in (IntersectionObserver's first callback fires for them almost
    // immediately) — the visitor never scrolled to "reveal" them, so all that
    // translateY animation was actually doing was moving already-visible layout on
    // every load, which is exactly what the Cumulative Layout Shift metric penalizes.
    // Reveal those instantly, with no transition; only cards below the fold — the ones
    // an actual scroll brings into view — get the animated version.
    const vh = window.innerHeight || document.documentElement.clientHeight;
    const toObserve = [];
    cards.forEach((el) => {
        if (el.getBoundingClientRect().top < vh) {
            el.classList.add('cw-reveal-instant', 'cw-in-view');
        } else {
            toObserve.push(el);
        }
    });
    if (!toObserve.length) return;

    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.classList.add('cw-in-view');
                observer.unobserve(entry.target);
            }
        });
    }, { threshold: 0.08, rootMargin: '0px 0px -40px 0px' });
    toObserve.forEach((el, i) => {
        el.style.transitionDelay = `${Math.min(i * 40, 240)}ms`;
        observer.observe(el);
    });
})();